mapper.select:
select t.* from ( select pebi.id as mainId, '一般立项' as projectEstablishType, pebi.proj_name as projName, pebi.proj_establish_status as projectEstablishStatus, pebi.proj_establish_process_status as projectEstablishProcessStatus, c.id as clientId, c.client_name as clientName, pebi.create_time as createTime, workday(pebi.create_time, now()) as workdaysOnStage, case pebi.biz_type when 'ZR' then peap.apply_credit_amount when 'BL' then pefp.apply_credit_amount else pelp.apply_credit_amount end as creditAmount, cci.risk_control_industry_classify as riskControlIndustryClassifyCode, it.code as industryCode, it.display as industryDisplay, pebi.biz_type as bizTypeCode, pebi.lessee_info as lesseeInfoJson, pebi.guarantee_info as guaranteeInfoJson, pebi.biz_dept_id as bizDeptId, pebi.proj_sponsor_user_id as projSponsorUserId, pebi.proj_cosponsor_user_ids as projCosponsorUserIdsJson, ahp.START_TIME_ as processInstanceStartTime, ahp.END_TIME_ as processInstanceEndTime, if (ahp.START_TIME_ is null, null, if (ahp.END_TIME_ is null, null, workday(ahp.START_TIME_, ahp.END_TIME_))) as processWorkdays, pebi.risk_control_manager_id as risk_control_manager_id, ahp.source_status as processInstanceStatus from proj_establish_base_info as pebi left join proj_establish_lease_price as pelp on pebi.id = pelp.proj_establish_id left join proj_establish_factoring_price as pefp on pebi.id = pefp.proj_establish_id left join proj_establish_aoc_price as peap on pebi.id = peap.proj_establish_id left join client as c on pebi.client_id = c.id left join corp_commerce_info as cci on c.id = cci.client_id left join industry_type as it on substr(cci.industry_type,1,1) = it.code and it.level = 1 left join ( select ahp.BUSINESS_KEY_, ahp.START_TIME_, ahp.END_TIME_, bs.source_status from act_hi_procinst as ahp inner join business_status as bs on ahp.PROC_INST_ID_ = bs.source_id and bs.source_type = 1 and source_status in (1,2,6) where ahp.PROC_DEF_ID_ in (select ID_ from act_re_procdef where KEY_ = 'ProjEstablishCreateFlow') ) as ahp on pebi.id = ahp.BUSINESS_KEY_ where pebi.id not in (select proj_establish_id from proj_review_base_info where proj_establish_id is not null) and pebi.proj_establish_status <> 'CLOSED' and pebi.proj_establish_status <> 'EXPIRE' union select gcebi.id as mainId, '授信立项' as projectEstablishType, gcebi.proj_name as projectEstablishName, gcebi.group_credit_establish_status as projectEstablishStatus, gcebi.group_credit_establish_process_status as projectEstablishProcessStatus, c.id as clientId, c.client_name as clientName, gcebi.create_time as createTime, workday(gcebi.create_time, now()) as workdaysOnStage, gcebi.apply_credit_amount as creditAmount, cci.risk_control_industry_classify as riskControlIndustryClassifyCode, it.code as industryCode, it.display as industryDisplay, '' as bizTypeCode, '' as lesseeInfoJson, '' as guaranteeInfoJson, gcebi.biz_dept_id as bizDeptId, gcebi.proj_sponsor_user_id as projSponsorUserId, gcebi.proj_cosponsor_user_ids as projCosponsorUserIdsJson, ahp.START_TIME_ as processInstanceStartTime, ahp.END_TIME_ as processInstanceEndTime, if (ahp.START_TIME_ is null, null, if (ahp.END_TIME_ is null, null, workday(ahp.START_TIME_, ahp.END_TIME_))) as processWorkdays, gcebi.risk_control_manager_id as risk_control_manager_id, ahp.source_status as processInstanceStatus from group_credit_establish_base_info as gcebi left join group_credit_review_base_info as gcrbi on gcebi.id = gcrbi.group_credit_establish_id left join client as c on gcebi.client_id = c.id left join corp_commerce_info as cci on c.id = cci.client_id left join industry_type as it on substr(cci.industry_type,1,1) = it.code and it.level = 1 left join ( select ahp.BUSINESS_KEY_, ahp.START_TIME_, ahp.END_TIME_, bs.source_status from act_hi_procinst as ahp inner join business_status as bs on ahp.PROC_INST_ID_ = bs.source_id and bs.source_type = 1 and source_status in (1,2,6) where ahp.PROC_DEF_ID_ in (select ID_ from act_re_procdef where KEY_ = 'GroupCreditEstablishCreateFlow') ) as ahp on gcebi.id = ahp.BUSINESS_KEY_ where (gcrbi.id is null or gcrbi.id not in (select group_credit_review_id from proj_review_base_info where group_credit_review_id is not null)) and gcebi.group_credit_establish_status <> 'CLOSED' and gcebi.group_credit_establish_status <> 'EXPIRE' ) as t where 1 = 1
and t.clientId = #{clientId}
and t.projName like concat('%', #{projName}, '%')
and t.projectEstablishStatus = #{projectEstablishStatus}
and t.projectEstablishProcessStatus = #{projectEstablishProcessStatus}
and t.bizDeptId = #{bizDeptId}
and t.projSponsorUserId = #{projSponsorUserId}
and t.bizDeptId in
#{item}
and ( t.projSponsorUserId = #{authCurrentUserId} or json_contains(t.projCosponsorUserIdsJson, cast( #{authCurrentUserId} as json) ) )
and JSON_CONTAINS(t.risk_control_manager_id, cast( #{accountVO.id} as json))
order by createTime desc

select prbi.id as mainId, prbi.proj_review_status as projReviewStatus, prbi.proj_review_process_status as projReviewProcessStatus, prbi.client_id as clientId, c.client_name as clientName, prbi.proj_name as projName, prbi.create_time as createTime, workday(prbi.create_time, now()) as workdaysOnStage, case prbi.biz_type when 'ZR' then prap.apply_credit_amount when 'BL' then prfp.apply_credit_amount else prlp.apply_credit_amount end as creditAmount, cci.risk_control_industry_classify as riskControlIndustryClassifyCode, it.code as industryCode, it.display as industryDisplay, prbi.biz_type as bizTypeCode, prbi.lessee_info as lesseeInfoJson, prbi.guarantee_info as guaranteeInfoJson, prbi.biz_dept_id as bizDeptId, prbi.proj_sponsor_user_id as projSponsorUserId, prbi.proj_cosponsor_user_ids as projCosponsorUserIdsJson, ahp.START_TIME_ as processInstanceStartTime, ahp.END_TIME_ as processInstanceEndTime, if (ahp.START_TIME_ is null, null, if (ahp.END_TIME_ is null, null, workday(ahp.START_TIME_, ahp.END_TIME_))) as processWorkdays, prbi.risk_control_manager_id as risk_control_manager_id, ahp.source_status as processInstanceStatus from proj_review_base_info as prbi left join proj_review_lease_price as prlp on prbi.id = prlp.project_id left join proj_review_factoring_price as prfp on prbi.id = prfp.project_id left join proj_review_aoc_price as prap on prbi.id = prap.project_id left join client as c on prbi.client_id = c.id left join corp_commerce_info as cci on c.id = cci.client_id left join industry_type as it on substr(cci.industry_type,1,1) = it.code and it.level = 1 left join ( select ahp.BUSINESS_KEY_, ahp.START_TIME_, ahp.END_TIME_, bs.source_status from act_hi_procinst as ahp inner join business_status as bs on ahp.PROC_INST_ID_ = bs.source_id and bs.source_type = 1 and source_status in (1,2,6) where ahp.PROC_DEF_ID_ in (select ID_ from act_re_procdef where KEY_ = 'ProjReviewCreateFlow') ) as ahp on prbi.id = ahp.BUSINESS_KEY_ where 1 = 1
and prbi.proj_review_status = 'NEW'
and prbi.proj_review_status = 'TAKE_EFFECT' and prbi.id not in (select proj_review_id from contract_base_info)
and ahp.source_status = 1 and prbi.id not in (select belong_id from materials_list where business_type = 'PROJ_REVIEW' and materials_type = 'LEGAL_COMPLIANCE_REPORT')
and prbi.client_id = #{clientId}
and prbi.proj_name like concat('%', #{projName}, '%')
and prbi.proj_review_status = #{projectReviewStatus}
and prbi.proj_review_process_status = #{projectReviewProcessStatus}
and prbi.biz_dept_id = #{bizDeptId}
and prbi.proj_sponsor_user_id = #{projSponsorUserId}
and prbi.biz_dept_id in
#{item}
and ( prbi.proj_sponsor_user_id = #{authCurrentUserId} or json_contains(prbi.proj_cosponsor_user_ids, cast( #{authCurrentUserId} as json) ) )
and prbi.risk_control_manager_id = #{accountVO.id}
order by createTime desc

select cbi.id as mainId, cbi.contract_code as contractCode, cbi.contract_status as contractStatus, cbi.contract_process_status as contractProcessStatus, cbi.client_id as clientId, c.client_name as clientName, cbi.proj_name as projName, cbi.create_time as createTime, workday(cbi.create_time, now()) as workdaysOnStage, cbi.apply_credit_amount as creditAmount, case cbi.biz_type when 'ZR' then cap.contract_amount when 'BL' then cfp.contract_amount else clp.apply_credit_amount end as contractAmount, case cbi.biz_type when 'ZR' then cap.lpr_percent when 'BL' then cfp.lpr_percent else clp.lpr_percent end as lprPercent, case cbi.biz_type when 'ZR' then cap.lpr_add_percent when 'BL' then cfp.lpr_add_percent else clp.lpr_add_percent end as lprAddPercent, case cbi.biz_type when 'ZR' then cap.aoc_credit_term when 'BL' then cfp.factoring_credit_term else clp.lease_month_count end as leaseDuration, cci.risk_control_industry_classify as riskControlIndustryClassifyCode, it.code as industryCode, it.display as industryDisplay, cbi.biz_type as bizTypeCode, cbi.biz_dept_id as bizDeptId, cbi.proj_sponsor_user_id as projSponsorUserId, cbi.proj_cosponsor_user_ids as projCosponsorUserIdsJson, ahp.START_TIME_ as processInstanceStartTime, ahp.END_TIME_ as processInstanceEndTime, if (ahp.START_TIME_ is null, null, if (ahp.END_TIME_ is null, null, workday(ahp.START_TIME_, ahp.END_TIME_))) as processWorkdays, cbi.risk_control_manager_id as risk_control_manager_id, ahp.source_status as processInstanceStatus from contract_base_info as cbi left join contract_lease_price as clp on cbi.id = clp.contract_id left join contract_factoring_price as cfp on cbi.id = cfp.contract_id left join contract_aoc_price as cap on cbi.id = cap.contract_id left join client as c on cbi.client_id = c.id left join corp_commerce_info as cci on c.id = cci.client_id left join industry_type as it on substr(cci.industry_type,1,1) = it.code and it.level = 1 left join ( select ahp.BUSINESS_KEY_, ahp.START_TIME_, ahp.END_TIME_, bs.source_status from act_hi_procinst as ahp inner join business_status as bs on ahp.PROC_INST_ID_ = bs.source_id and bs.source_type = 1 and source_status in (1,2,6) where ahp.PROC_DEF_ID_ in (select ID_ from act_re_procdef where KEY_ = 'ContractCreateFlow') ) as ahp on cbi.id = ahp.BUSINESS_KEY_ where cbi.contract_status not in ('CLOSED','INVALID') and cbi.id not in (select contract_id from payment_base_info)
and cbi.client_id = #{clientId}
and cbi.contract_code like concat('%', #{contractCode}, '%')
and cbi.contract_process_status = #{contractProcessStatus}
and cbi.biz_dept_id = #{bizDeptId}
and cbi.proj_sponsor_user_id = #{projSponsorUserId}
and cbi.biz_dept_id in
#{item}
and ( cbi.proj_sponsor_user_id = #{authCurrentUserId} or json_contains(cbi.proj_cosponsor_user_ids, cast( #{authCurrentUserId} as json) ) )
and cbi.risk_control_manager_id = #{accountVO.id}
and cbi.proj_name like concat('%', #{projName}, '%')
order by createTime desc

select pbi.id as mainId, pbi.payment_code as paymentCode, cbi.contract_code as contractCode, pbi.payment_status as paymentStatus, pbi.payment_process_status as paymentProcessStatus, cbi.client_id as clientId, c.client_name as clientName, cbi.proj_name as projName, pbi.create_time as createTime, workday(pbi.create_time, now()) as workdaysOnStage, pbi.apply_payment_amount as applyPayAmount, pbi.apply_payment_date as applyPayDate, case cbi.biz_type when 'ZR' then cap.contract_amount when 'BL' then cfp.contract_amount else clp.apply_credit_amount end as contractAmount, case cbi.biz_type when 'ZR' then cap.lpr_percent when 'BL' then cfp.lpr_percent else clp.lpr_percent end as lprPercent, case cbi.biz_type when 'ZR' then cap.lpr_add_percent when 'BL' then cfp.lpr_add_percent else clp.lpr_add_percent end as lprAddPercent, case cbi.biz_type when 'ZR' then cap.aoc_credit_term when 'BL' then cfp.factoring_credit_term else clp.lease_month_count end as leaseDuration, cci.risk_control_industry_classify as riskControlIndustryClassifyCode, it.code as industryCode, it.display as industryDisplay, cbi.biz_type as bizTypeCode, cbi.biz_dept_id as bizDeptId, cbi.proj_sponsor_user_id as projSponsorUserId, cbi.proj_cosponsor_user_ids as projCosponsorUserIdsJson, ahp.START_TIME_ as processInstanceStartTime, ahp.END_TIME_ as processInstanceEndTime, if (ahp.START_TIME_ is null, null, if (ahp.END_TIME_ is null, null, workday(ahp.START_TIME_, ahp.END_TIME_))) as processWorkdays, cbi.risk_control_manager_id as risk_control_manager_id, ahp.source_status as processInstanceStatus from payment_base_info as pbi left join contract_base_info as cbi on cbi.id = pbi.contract_id left join contract_lease_price as clp on cbi.id = clp.contract_id left join contract_factoring_price as cfp on cbi.id = cfp.contract_id left join contract_aoc_price as cap on cbi.id = cap.contract_id left join client as c on cbi.client_id = c.id left join corp_commerce_info as cci on c.id = cci.client_id left join industry_type as it on substr(cci.industry_type,1,1) = it.code and it.level = 1 left join ( select ahp.BUSINESS_KEY_, ahp.START_TIME_, ahp.END_TIME_, bs.source_status from act_hi_procinst as ahp inner join business_status as bs on ahp.PROC_INST_ID_ = bs.source_id and bs.source_type = 1 and source_status in (1,2,6) where ahp.PROC_DEF_ID_ in (select ID_ from act_re_procdef where KEY_ = 'PaymentCreateFlow') ) as ahp on pbi.id = ahp.BUSINESS_KEY_ where 1 = 1
and pbi.payment_status = 'NEW'
and pbi.payment_status = 'TAKE_EFFECT' and pbi.id not in (select payment_id from payment_actual_detail)
and cbi.client_id = #{clientId}
and pbi.apply_payment_date >= #{applyPayDateFrom}
and pbi.apply_payment_date <= #{applyPayDateTo}
and cbi.contract_code like concat('%', #{contractCode} , '%')
and pbi.payment_status = #{paymentStatus}
and pbi.payment_process_status = #{paymentProcessStatus}
and cbi.biz_dept_id = #{bizDeptId}
and cbi.proj_sponsor_user_id = #{projSponsorUserId}
and cbi.biz_dept_id in
#{item}
and ( cbi.proj_sponsor_user_id = #{authCurrentUserId} or json_contains(cbi.proj_cosponsor_user_ids, cast( #{authCurrentUserId} as json) ) )
and cbi.risk_control_manager_id = #{accountVO.id}
order by createTime desc
